css:
.signed-in .loadPetala{
	display:none;
}
.loadPetala svg{
            height: 150px;
            width:150px;
        }
       .loadPetala .areaLoad{
            position: fixed;
            top: 0;
            width: 100%;
            height: 100vh;
            background: var(--gray-light);
            z-index: 99;
            display: flex;
            align-items: center;
            justify-content: space-around;
        }
        .petala {
            opacity: 0;
            animation: aparecer 2.6s infinite ease-in-out;
        }

        .petala:nth-child(1) { animation-delay: 0.4s; }
        .petala:nth-child(2) { animation-delay: 0.8s; }
        .petala:nth-child(3) { animation-delay: 1.2s; }
        .petala:nth-child(4) { animation-delay: 1.6s; }
        .petala:nth-child(5) { animation-delay: 2s; }
        .petala:nth-child(6) { animation-delay: 2.4s; }

        @keyframes aparecer {
            0% { opacity: 0; }
            80% { opacity: 1; }
            100% { opacity: 0.5; }

        }

