$(document).ready(function () {
            // Aguarda 3 segundos e remove o loader
            setTimeout(function () {
                $(".loadPetala").fadeOut(500, function () {
                    $(this).remove(); // Remove o loader do DOM
                });
            }, 3000);
        });;

