$(document).ready(() => {
    const carousel = $('.sv-area-carrossel .carrossel');

    carousel.slick({
        infinite: false,
        slidesToShow: 2.4,
        slidesToScroll: 1,
        dots: false,
        prevArrow: `<button class="slick-prev bg-secondary font-size-medium color-white d-flex align-items-center justify-content-center ml-4 z-1 opacity-50">
                      <img alt="icone seta esquerda" src="data:image/png;base64," />
                    </button>`,
        nextArrow: `<button class="slick-next bg-secondary font-size-medium color-white d-flex align-items-center justify-content-center mr-5 z-1">
                      <img alt="icone seta direita" src="data:image/png;base64," />
                    </button>`,
        responsive: [
            {
                breakpoint: 768,
                settings: {
                  slidesToShow: 1,
                  prevArrow: `<button class="slick-prev bg-secondary font-size-medium color-white d-flex align-items-center justify-content-center ml-4 z-1 opacity-50">
                                  <img alt="icone seta esquerda" src="data:image/png;base64," />
                              </button>`,
                  nextArrow: `<button class="slick-next bg-secondary font-size-medium color-white d-flex align-items-center justify-content-center mr-4 z-1">
                                  <img alt="icone seta direita" src="data:image/png;base64," />
                              </button>`
                }
            },
        ]
    });

    function updateArrowOpacity(slick, currentSlide) {
        const totalSlides = slick.slideCount;
        const slidesToShow = slick.options.slidesToShow;
        const prevButton = $('.sv-area-carrossel .slick-prev');
        const nextButton = $('.sv-area-carrossel .slick-next');
        const isDesktop = window.innerWidth >= 768;

        if (currentSlide === 0) {
            prevButton.addClass('opacity-50');
        } else {
            prevButton.removeClass('opacity-50');
        }

        if (currentSlide >= totalSlides - slidesToShow) {
            if (isDesktop) {
                nextButton.removeClass('mr-5');
                nextButton.addClass('mr-4');
            }
            nextButton.addClass('opacity-50');
        } else {
            if (isDesktop) {
                nextButton.removeClass('mr-4');
                nextButton.addClass('mr-5');
            }
            nextButton.removeClass('opacity-50');
        }
    }

    carousel.on('afterChange', function (event, slick, currentSlide) {
        updateArrowOpacity(slick, currentSlide);
    });

    carousel.on('init', function (event, slick) {
        updateArrowOpacity(slick, 0);
    });

    carousel.slick('setPosition');

    let carousels = [];

    document.querySelectorAll(".sv-area-carrossel .slide-card").forEach((slideCard, index) => {
        let titleElement = slideCard.querySelector(".slide-card-description p");
        let title = titleElement ? titleElement.textContent.trim() : "";
        let anchorURL = `${window.location.href}#${slideCard.id}`;

        carousels.push({
            "@type": "ListItem",
            "title": title,
            "url": anchorURL,
            "position": index
        });
    });

    let jsonLd = {
        "@context": "https://schema.org",
        "@type": "ItemList",
        "itemListElement": carousels
    };

    let script = document.createElement("script");
    script.type = "application/ld+json";
    script.textContent = JSON.stringify(jsonLd, null, 2);
    document.head.appendChild(script);    
});;

