const fragmentContainer = fragmentElement.querySelector('.global-banner-with-boxes');

if(fragmentContainer){
    const textContainer = fragmentContainer.querySelector(".main-content .main-container .text-container")
    if(textContainer){
        const titleElement = textContainer.querySelector('.title-content');
        const match = titleElement.textContent.match(/^[^.?!]*[.?!]/);
        if (match) {
            const firstSentence = match[0];
            const textWithBreaks = firstSentence.replace(/([.?!,])(?!\s*$)/g, '$1<br>');
            titleElement.innerHTML = textWithBreaks;
        }
    }
};

