Pagina.pronta(function () {
	var $slider = $('.sv-bannerSlideSecundario .slideBannerSecundario');
	var totalSlides = $slider.children().length;
	var tempoSlide = parseInt($('.sv-bannerSlideSecundario').attr('data-temposlide')) || 15000;
	if (totalSlides === 1) {
        // Se houver apenas um slide, exibe corretamente o conteúdo do slide
        $('.sv-bannerSlideSecundario .slideBannerSecundario .bannerSlideSecundario__content').css({
            'opacity': '1',
            'visibility': 'visible'
        });
    }
	if ($slider.children().length > 1) {
        $slider.slick({
          dots: true,
          infinite: false,
          speed: 600,
					autoplaySpeed: tempoSlide, 
          slidesToShow: 1,
          autoplay: true,
          arrows: false,
					accessibility: true,
          responsive: [
        {
        breakpoint: 768, 
        settings: {
            slidesToShow: 1,
            slidesToScroll: 1
        }
    }
]
            });      
        $('.sv-bannerSlideSecundario .slideBannerSecundario .slick-dots').addClass('container');

	}
});;

