js:
Pagina.pronta(function () {
    var $slider = $('.sv-slideTextos .slideText');
    var totalSlides = $slider.children().length;
    var ordemDesejada = [3, 1, 5, 0, 4, 2];
    var $rosetas = $('.rosetasModel.dots-petalas .dot-petala');
    var $paths = $('svg path[id^="traco"]');
    var tempoSlide = parseInt($('.sv-slideTextos .slideText').attr('data-temposlide')) || 30000;
    // Garante que o slide de texto sempre seja visível
    $slider.css('display', 'block').css('opacity', 1);

    // Oculta todas as rosetas e paths antes de exibir os corretos
    $rosetas.css('opacity', 0);
    $paths.css('opacity', 0);

    // Exibe apenas as rosetas e paths correspondentes à quantidade de slides
    ordemDesejada.forEach(function (ordemIndex, i) {
        if (i < totalSlides) {
            $rosetas.eq(ordemIndex).css('opacity', 1);
            $paths.eq(ordemIndex).css('opacity', 1);
        }
    });

    // Define a primeira pétala ativa corretamente
    if (totalSlides > 0) {
        $rosetas.eq(ordemDesejada[0]).addClass('active');
    }

    if (totalSlides === 1) {
        // Se houver apenas um slide, exibe corretamente o conteúdo do slide
        $('.sv-slideTextos .slideText .slideTex__content').css({
            'opacity': '1',
            'visibility': 'visible'
        });
    }

    if (totalSlides > 1) {
        // Inicializa o slider se houver mais de um slide
        $slider.slick({
            dots: true,
            infinite: false,
            speed: 600,
            slidesToShow: 1,
            autoplay: true,
            accessibility: true,
            autoplaySpeed: tempoSlide,
            arrows: false,
        });

        // Evento de clique nas rosetas do primeiro SVG
        $rosetas.on('click', function () {
            var realIndex = $rosetas.index(this);
            var slideIndex = ordemDesejada.indexOf(realIndex);
            if (slideIndex !== -1) {
                $slider.slick('slickGoTo', slideIndex);
            }
        });

        // Atualiza a classe ativa nos dois modelos quando o slide muda
        $slider.on('afterChange', function (event, slick, currentSlide) {
            // Atualiza o modelo 1
            $rosetas.removeClass('active');
            $rosetas.eq(ordemDesejada[currentSlide]).addClass('active');

            // Atualiza os paths do svg visíveis
            $paths.css('opacity', 0);
            $rosetas.each(function (index) {
                if ($(this).css('opacity') == '1') {
                    $paths.eq(index).css('opacity', 1);
                }
            });

            // Atualiza o modelo 2
            $('.rosetasModel2.dots-petalas .dot-petala').removeClass('active')
                .eq(currentSlide).addClass('active');
        });

        // Configuração inicial do modelo 2
        var $rosetasModel2 = $('.rosetasModel2.dots-petalas .dot-petala');
        $rosetasModel2.each(function (index) {
            $(this).attr('data-slide', index);
        }).first().addClass('active');

        // Evento de clique para mudar de slide no modelo 2
        $rosetasModel2.on('click', function () {
            var index = $(this).data('slide');
            if (index !== undefined) {
                console.log("Mudando para slide:", index);
                $slider.slick('slickGoTo', index);
            } else {
                console.error("Erro: data-slide não definido para a pétala clicada.");
            }
        });
    }
});;

