var videoContainers = document.querySelectorAll('.areaVideoYoutube');

videoContainers.forEach(function(videoContainer) {
    var videoThumbnail = videoContainer.querySelector('.videoThumbnail');
    var videoIframe = videoContainer.querySelector('.video iframe');
    var videoUrl = videoContainer.getAttribute('data-video');

    var videoImgThumbnail = videoThumbnail.querySelector('img');
    videoImgThumbnail.src = getVideoThumbnail(videoUrl);

    function playVideo(unmute = false) {
        videoThumbnail.style.display = 'none';
        videoIframe.src = getVideoUrl(videoUrl, unmute);
        videoIframe.style.display = 'flex';
    }

    // Evento de clique para ativar o vídeo
    videoThumbnail.addEventListener('click', function() {
        playVideo(false);
    });

    // Evento de teclado para ativar o vídeo ao pressionar "Enter" ou "Espaço"
    videoThumbnail.addEventListener('keydown', function(event) {
        if (event.key === "Enter" || event.key === " ") {
            playVideo(true);
        }
    });
});


function getVideoUrl(url, unmute = false) {
    if (!url.includes('http://') && !url.includes('https://'))
        url = `https://${url}`;

    if (!url?.includes('youtube.com') && !url?.includes('youtu.be'))
        return ['', ''];

    if (url?.includes('v=')) {
        const newURL = new URL(url);
        const v = newURL.searchParams.get('v');
        return `https://www.youtube.com/embed/${v}?autoplay=1${unmute ? '' : '&mute=1'}`;
    } else {
        const newURL = new URL(url);
        const v = newURL.pathname.replace('/', '').replace('embed/', '');
        return `https://www.youtube.com/embed/${v}?autoplay=1${unmute ? '' : '&mute=1'}`;
    }
}

function getVideoThumbnail  (url) {
    if (!url.includes('http://') && !url.includes('https://'))
      url = `https://${url}`

    if (!url?.includes('youtube.com') && !url?.includes('youtu.be'))
      return ['', '']
    if (url?.includes('v=')) {
      const newURL = new URL(url)
      const v = newURL.searchParams.get('v')
      return `https://img.youtube.com/vi/${v}/maxresdefault.jpg`;
    } else {
      const newURL = new URL(url)
      const v = newURL.pathname.replace('/', '').replace('embed/', '');
      return `https://img.youtube.com/vi/${v}/maxresdefault.jpg`;
    }
  };

