js:
$(document).ready(() => {
    const navPills = $(".sv-nosso-novo-branding .nav-pills");
    const carousel = $(".sv-nosso-novo-branding .carousel");

    function toggleCarousel() {
        const isMobile = window.innerWidth <= 768;

        if (isMobile && !navPills.hasClass("tab-options-carousel")) {
            navPills.addClass("tab-options-carousel");
            initCarousel();
        } else if (!isMobile && navPills.hasClass("tab-options-carousel")) {
            destroyCarousel();
            navPills.removeClass("tab-options-carousel");
        }
    }

    function initCarousel() {
        $(".sv-nosso-novo-branding .tab-options-carousel").not('.slick-initialized').slick({
            dots: false,
            infinite: false,
            speed: 300,
            slidesToShow: 1,
            adaptiveHeight: true,
            prevArrow: `<button class="slick-prev font-size-medium color-secondary d-flex align-items-center justify-content-center ml-2 ml-md-5 z-1">
                            <img src="data:image/png;base64," alt="icone-seta-esquerda" />
                        </button>`,
            nextArrow: `<button class="slick-next font-size-medium color-secondary d-flex align-items-center justify-content-center mr-2 mr-md-5 z-1">
                            <img src="data:image/png;base64," alt="icone-seta-direita"/>
                        </button>`
        });
    }

    function destroyCarousel() {
        const tabOptionsCarousel = $(".sv-nosso-novo-branding .tab-options-carousel");
        if (tabOptionsCarousel.hasClass("slick-initialized")) {
            tabOptionsCarousel.slick("unslick");
        }
    }

    toggleCarousel();

    $(window).resize(() => {
        toggleCarousel();
    });

    $(".sv-nosso-novo-branding .tab-options-carousel").on("afterChange", function () {
        const target = $(".tab-options-carousel .slick-active").attr("data-bs-target");

        $(".nav-pills button").removeClass("active");
        $(".tab-pane").removeClass("show active");
        $(target).addClass("show active");

        setTimeout(() => {
            carousel.slick("setPosition");
            carousel.slick("slickGoTo", 0);
        }, 100);
    });

    $("button[data-bs-toggle='pill']").on("shown.bs.tab", function () {
        setTimeout(() => {
            carousel.slick("setPosition");
            carousel.slick("slickGoTo", 0);
        }, 100);
    });
});;

