js:
$(document).ready(() => {
  function initCarousel(carousel) {
    let slideCount = carousel.children().length;

    // Se o carrossel já está inicializado, remove antes de recriar
    if (carousel.hasClass("slick-initialized")) {
      carousel.slick("unslick");
    }

    carousel.slick({
      dots: slideCount > 1,
      infinite: slideCount > 1,
      slidesToShow: 1,
      slidesToScroll: 1,
      prevArrow: `<button class="slick-prev bg-secondary font-size-medium color-white d-flex align-items-center justify-content-center ml-2 ml-md-5 z-1 opacity-50">
                    <img alt="icone seta esquerda" src="data:image/png;base64," />
                  </button>`,
      nextArrow: `<button class="slick-next bg-secondary font-size-medium color-white d-flex align-items-center justify-content-center mr-2 mr-md-5 z-1">
                    <img alt="icone seta direita" src="data:image/png;base64," />
                  </button>`,
      responsive: [
        {
          breakpoint: 768,
          settings: {
            slidesToShow: 1
          }
        },
      ]
    });
  }

  // Se o carrossel estiver **fora** de uma aba navegável, inicializa imediatamente
  $(".sv-carrossel-simples .carousel").each(function () {
    if (!$(this).closest(".tab-pane").length) {
      initCarousel($(this));
    }
  });

  // Se o carrossel estiver **dentro** de uma aba navegável, inicializa apenas quando a aba for ativada
  $("button[data-bs-toggle='pill']").on("shown.bs.tab", function (e) {
    let targetTab = $(e.target).attr("data-bs-target");
    let carousel = $(targetTab).find(".sv-carrossel-simples .carousel");

    if (carousel.length) {
      setTimeout(() => {
        initCarousel(carousel);
      }, 200); // Pequeno delay para evitar conflitos
    }
  });

  // Se uma aba navegável já estiver ativa ao carregar a página, inicializa o carrossel nela
  $(".tab-pane.active .sv-carrossel-simples .carousel").each(function () {
    initCarousel($(this));
  });

  // Gerar JSON-LD para SEO
  let carousels = [];

  document.querySelectorAll(".sv-carrossel-simples .sv-carrossel-simples-slide").forEach((slide, index) => {
      let anchorURL = `${window.location.href}#${slide.id}`;

      carousels.push({
          "@type": "ListItem",
          "url": anchorURL,
          "position": index
      });
  });

  let jsonLd = {
      "@context": "https://schema.org",
      "@type": "ItemList",
      "itemListElement": carousels
  };

  let script = document.createElement("script");
  script.type = "application/ld+json";
  script.textContent = JSON.stringify(jsonLd, null, 2);
  document.head.appendChild(script);

});;

